<?php
require_once __DIR__ . '/../includes/bootstrap.php';$pageTitle='Sales';$activePage='sales/index.php';$basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{$date=(string)($_POST['sale_date']??date('Y-m-d'));$bill=trim((string)($_POST['bill_number']??''));$ids=$_POST['product_id']??[];$quantities=$_POST['quantity']??[];$prices=$_POST['unit_selling_price']??[];if($bill==='')throw new RuntimeException('Bill number is required.');if(!DateTime::createFromFormat('Y-m-d',$date))throw new RuntimeException('Invalid sales date.');$lines=[];foreach($ids as $i=>$pid){if((int)$pid<1)continue;$q=positive_decimal($quantities[$i]??null,'Sale quantity');$priceRaw=$prices[$i]??'';$lines[]=['id'=>(int)$pid,'qty'=>$q,'price'=>$priceRaw===''?null:nonnegative_money($priceRaw,'Selling price')];}if(!$lines)throw new RuntimeException('Add at least one product line.');
 $pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO sales(sale_date,bill_number) VALUES(?,?)');$s->execute([$date,$bill]);$saleId=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_selling_price,unit_cost_at_sale) VALUES(?,?,?,?,?)');
 foreach($lines as $line){$row=inventory_row($pdo,$line['id']);$price=$line['price']??(float)$row['selling_price'];$cost=apply_outbound($pdo,$line['id'],'SALE',$line['qty'],'Sale recorded',$bill,$date . ' ' . date('H:i:s'));$item->execute([$saleId,$line['id'],$line['qty'],$price,$cost]);}
 $pdo->commit();flash('success','Sale '.$bill.' recorded. Stock reduced and cost of goods sold captured.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Sale was not saved: '.$e->getMessage());}redirect('index.php');
}
$products=product_options($pdo);$history=$pdo->query('SELECT s.sale_id,s.sale_date,s.bill_number,COALESCE(SUM(si.quantity*si.unit_selling_price),0) revenue,COALESCE(SUM(si.quantity*si.unit_cost_at_sale),0) cogs FROM sales s LEFT JOIN sale_items si ON si.sale_id=s.sale_id GROUP BY s.sale_id ORDER BY s.sale_date DESC,s.sale_id DESC LIMIT 30')->fetchAll();
require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">STOCK OUT</p><h1>Sales</h1><p class="muted">Enter counter sales. Available stock is checked before a bill is committed.</p></div></section>
<section class="panel"><h2>Record a sale</h2><?php if(!$products):?><div class="alert warning">Add products before recording sales.</div><?php else:?><form method="post"><?=csrf_field()?><div class="form-grid two"><label>Sale date<input type="date" name="sale_date" required value="<?=date('Y-m-d')?>"></label><label>Bill number<input name="bill_number" required maxlength="50" placeholder="BILL-2026-001"></label></div><div class="line-items"><div class="line-heading"><h3>Sold products</h3><button class="btn secondary small" type="button" data-add-row="sale">+ Add product</button></div><div id="sale-lines"><div class="item-row sale-row"><label>Product<select name="product_id[]" required><option value="">Select product</option><?php foreach($products as $p):?><option value="<?=(int)$p['product_id']?>" data-price="<?=e($p['selling_price'])?>"><?=e($p['product_name'])?> (<?=e($p['unit'])?>)</option><?php endforeach;?></select></label><label>Quantity<input name="quantity[]" type="number" min="0.001" step="0.001" required placeholder="e.g. 1.500"></label><label>Selling price / unit (₹)<input name="unit_selling_price[]" type="number" min="0" step="0.01" placeholder="Leave blank for product price"></label><button class="remove-row" type="button" aria-label="Remove row">×</button></div></div></div><button class="btn primary" type="submit">Save sale and update stock</button></form><?php endif;?></section>
<section class="panel"><div class="panel-heading"><h2>Recent sales</h2><span class="count-label">Latest 30</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Bill</th><th>Sales revenue</th><th>COGS</th><th>Gross profit</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e(date('d M Y',strtotime($h['sale_date'])))?></td><td><?=e($h['bill_number'])?></td><td><?=money($h['revenue'])?></td><td><?=money($h['cogs'])?></td><td><?=money($h['revenue']-$h['cogs'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
